# Neue japanische Crews
CREWS_B = [
dict(id='t_zangyo', name='Zangyō Express', jp='残業エクスプレス', color='#8fa3b8', tier=0, region='shinagawa',
 desc=('Angestellte, die nach der Überstunde nicht nach Hause wollen. Krawatte locker, Aktentasche auf dem Beifahrersitz, Firmenwagen am Limit.',
       'Office workers who do not want to go home after overtime. Tie loosened, briefcase on the passenger seat, company car at the limit.'),
 leader=('midsize/special', 'Shūhei Kachō', 'Der Abteilungsleiter', 'The Section Chief',
   'Hat seit 1996 keinen Urlaubstag genommen. Seine Mitarbeiter fahren gegen dich, damit er sie nicht befördern muss.',
   'Has not taken a day off since 1996. His staff race you so he does not have to promote them.', 'navy'),
 members=[
  ('sunburst2/base_EU_M', 'Tadashi Honda', 'Pendler', 'Commuter', 'Fährt seit 14 Jahren dieselbe Strecke. Heute zum ersten Mal schneller als 80.', 'Has driven the same route for 14 years. Tonight is the first time above 80.', 'silver'),
  ('sunburst2/base_EU_CVT', 'Michiko Aoyama', 'Excel-Göttin', 'Spreadsheet Goddess', 'Hat ihre Rundenzeiten in einer Pivot-Tabelle. Mit bedingter Formatierung.', 'Keeps her lap times in a pivot table. With conditional formatting.'),
  ('sunburst2/base_CVT', 'Hideo Kubo', 'Krawattenknoten', 'Tie Knot', 'Bindet seine Krawatte vor jedem Rennen neu. Doppelter Windsor, wegen der Aerodynamik.', 'Reties his tie before every race. Double Windsor, for aerodynamics.'),
  ('sunburst2/comfort_M', 'Kazue Sugawara', 'Kantinenchefin', 'Canteen Boss', 'Kocht für die ganze Firma und fährt mit Bento-Boxen im Kofferraum. Bremst deshalb sehr sanft.', 'Cooks for the whole company and races with bento boxes in the boot. So she brakes very gently.'),
  ('sunburst2/comfort_CVT', 'Masato Ikeda', 'Letzte Bahn', 'Last Train', 'Hat die letzte Bahn verpasst und beschlossen, es sei Schicksal. Fährt jetzt jede Nacht.', 'Missed the last train and decided it was fate. Now races every night.', 'silver'),
  ('midsize/DX_A', 'Junko Ebina', 'Kopiererin', 'Copy Queen', 'Kopiert deine Linie Kurve für Kurve. Wie im Büro, nur mit mehr Toner.', 'Copies your line corner by corner. Like at the office, but with more toner.'),
  ('midsize/DX_M', 'Toru Matsui', 'Praktikant', 'Intern', 'Ist seit sieben Jahren Praktikant. Hofft, dass ein Sieg gegen dich endlich eine Festanstellung bringt.', 'Has been an intern for seven years. Hopes a win against you finally gets him hired.'),
  ('midsize/LX_A', 'Reiko Hamada', 'Meeting-Marathon', 'Meeting Marathon', 'Hatte heute neun Meetings. Will jetzt einfach nur jemanden überholen.', 'Had nine meetings today. Now she just wants to overtake somebody.', 'white'),
  ('midsize/LX_M', 'Yoshio Kanno', 'Visitenkarte', 'Business Card', 'Überreicht dir vor dem Rennen mit beiden Händen seine Visitenkarte. Nach dem Rennen will er sie zurück.', 'Hands you his business card with both hands before the race. Wants it back afterwards.'),
  ('midsize/LX_V6_A', 'Satoshi Ueno', 'Nomikai', 'After-Work Drinks', 'Kommt vom Firmenessen und trinkt nur Oolong-Tee. Sagt er.', 'Comes straight from the company dinner and only had oolong tea. He says.'),
  ('midsize/LX_V6_M', 'Atsuko Kimura', 'Stempelkissen', 'Ink Stamp', 'Hat für jeden Sieg einen eigenen Hanko-Stempel. Für Niederlagen auch, der ist größer.', 'Has a personal hanko stamp for every win. One for losses too, and that one is bigger.'),
 ]),
dict(id='t_showa', name='Shōwa Retro Club', jp='昭和レトロ倶楽部', color='#d4a373', tier=1, region='himeji',
 desc=('Liebhaber alter Autos mit Chrom, Vergasern und Geduld. Ihr Durchschnittsalter ist höher als ihre Höchstgeschwindigkeit, aber sie haben Zeit.',
       'Fans of old cars with chrome, carburettors and patience. Their average age is higher than their top speed, but they have time.'),
 leader=('autobello/street', 'Toshirō Kaneda', 'Der Chrom-Kaiser', 'The Chrome Emperor',
   'Hat seinen Autobello 1971 in Neapel gekauft und eigenhändig nach Japan verschifft. Erzählt die Geschichte jede Woche länger.',
   'Bought his Autobello in Naples in 1971 and shipped it to Japan himself. The story gets longer every week.'),
 members=[
  ('miramar/base_M', 'Fumio Nagai', 'Vergaser', 'Carburettor', 'Stellt seinen Vergaser nach Gehör ein. Hört allerdings nicht mehr so gut.', 'Tunes his carburettor by ear. His hearing is not what it was.', 'teal'),
  ('miramar/base_facelift_M', 'Setsuko Nagai', 'Fumios Frau', 'Fumio\'s Wife', 'Fährt dasselbe Auto wie ihr Mann, nur in schön. Und schneller.', 'Drives the same car as her husband, but prettier. And faster.', 'cream'),
  ('miramar/sport', 'Isao Hirose', 'Rock and Roll', 'Rock and Roll', 'Hat eine Tolle wie 1963 und ein Kassettendeck mit genau einem Lied.', 'Has a quiff straight out of 1963 and a tape deck with exactly one song.', 'red'),
  ('miramar/sport_coupe', 'Kimiko Sasaki', 'Petticoat', 'Petticoat', 'Kam mit ihrem Coupé zum Tanztee und blieb für das Rennen.', 'Came to the tea dance in her coupé and stayed for the race.', 'sky'),
  ('miramar/sport_facelift', 'Masao Kudō', 'Der Sammler', 'The Collector', 'Besitzt 14 Miramar. Dieser ist der, den er am wenigsten liebt, deshalb darf er rennen.', 'Owns 14 Miramars. This is the one he loves least, so it is allowed to race.'),
  ('miramar/sport_coupe_facelift', 'Haruko Ōishi', 'Wählscheibe', 'Rotary Dial', 'Hat kein Handy, aber ein Autotelefon von 1979. Es funktioniert nicht, sie telefoniert trotzdem.', 'Has no mobile but a car phone from 1979. It does not work, she still talks into it.', 'mint'),
  ('miramar/miramighty', 'Gonzō Tabata', 'Mighty Gonzō', 'Mighty Gonzo', 'Hat in den Siebzigern angeblich mal den Kaiser überholt. Wird nie verraten, welchen.', 'Supposedly overtook the emperor back in the seventies. Will never say which one.'),
  ('autobello/150', 'Giulia Rossi', 'La Nonna', 'La Nonna', 'Zog 1975 aus Turin nach Kobe und kocht die beste Pasta der Präfektur. Fährt so, wie sie Knoblauch dosiert.', 'Moved from Turin to Kobe in 1975 and makes the best pasta in the prefecture. Drives the way she doses garlic.', 'italred'),
  ('autobello/150_track', 'Hiroshi Bello', 'Spaghetti-Hiro', 'Spaghetti Hiro', 'Giulias Enkel. Hat den 150 auf die Rennstrecke gebracht. Oma ist immer noch schneller.', 'Giulia\'s grandson. Took the 150 to the track. Grandma is still faster.'),
 ]),
dict(id='t_diana', name='Diana Sisters', jp='ダイアナ姉妹', color='#f48fb1', tier=1, region='kumamoto',
 desc=('Sechs Freundinnen aus Kumamoto, alle im Diana, alle mit Spitznamen, alle viel zu ehrgeizig. Wer eine schlägt, muss sich vor den anderen fünf hüten.',
       'Six friends from Kumamoto, all in Dianas, all with nicknames, all far too ambitious. Beat one and beware the other five.'),
 leader=('bx/diana_gtz_M', 'Aiko Hanazawa', 'Die große Schwester', 'Big Sister',
   'Hat die Sisters gegründet, weil ihr der Männer-Club zu langsam war. Ihr Diana GTz hat noch den Originalduft von 1990.',
   'Founded the Sisters because the boys\' club was too slow. Her Diana GTz still has its original 1990 smell.', 'rose'),
 members=[
  ('bx/diana_base_M', 'Momo Hanazawa', 'Die Kleine', 'Little One', 'Aikos jüngere Schwester. Darf erst mitfahren, seit sie die Schuhe der anderen putzt.', 'Aiko\'s little sister. Only allowed to join since she started polishing everyone\'s shoes.', 'peach'),
  ('bx/diana_base_A', 'Kana Uchida', 'Lipgloss', 'Lip Gloss', 'Zieht an jeder roten Ampel Lipgloss nach. Hat dabei noch nie die grüne verpasst.', 'Reapplies lip gloss at every red light. Has never missed the green.', 'lilac'),
  ('bx/diana_type_l_M', 'Natsumi Ono', 'Sommerkind', 'Summer Child', 'Fährt mit offenem Fenster, auch im Winter. Sagt, das sei gut für die Haut.', 'Drives with the window down, even in winter. Says it is good for the skin.', 'yellow'),
  ('bx/diana_type_l_A', 'Sakura Imai', 'Kirschblüte', 'Cherry Blossom', 'Hat Plastikblüten am Armaturenbrett. Bei Vollgas regnet es rosa.', 'Has plastic blossoms on her dashboard. At full throttle it rains pink.', 'pink'),
  ('bx/diana_type_ls_M', 'Rei Kurosawa', 'Die Ruhige', 'The Quiet One', 'Sagt selten etwas, aber ihr Auspuff hat eine Meinung.', 'Rarely says anything, but her exhaust has opinions.', 'dark'),
  ('bx/diana_type_ls_A', 'Yuka Ōta', 'Klatschmaul', 'Gossip', 'Weiß alles über jeden auf dem Ring. Weiß jetzt auch etwas über dich.', 'Knows everything about everyone on the loop. Now she knows something about you too.', 'coral'),
 ]),
dict(id='t_bxboys', name='Nihyaku Boys', jp='二百ボーイズ', color='#4fc3f7', tier=2, region='sapporo',
 desc=('Eine Clique aus Sapporo, die nur 200BX fährt. Sie streiten seit Jahren, ob Klappscheinwerfer schneller machen. Sie machen es nicht.',
       'A clique from Sapporo that only drives 200BX. They have argued for years whether pop-up headlights make you faster. They do not.'),
 leader=('bx/200bx_gtz_M', 'Daisuke Hokuto', 'Polarstern', 'Pole Star',
   'Kam mit seinem GTz Turbo aus Hokkaido und hat die Winterreifen nie gewechselt. Sagt, das sei Taktik.',
   'Came down from Hokkaido in his GTz Turbo and never swapped the winter tyres. Says it is tactics.', 'ice'),
 members=[
  ('bx/200bx_base_M', 'Kenji Ōno', 'Klappscheinwerfer', 'Pop-Up', 'Lässt seine Klappscheinwerfer im Takt der Musik auf und zu gehen. Die Lampen sind müde.', 'Flips his pop-up headlights to the beat. The motors are exhausted.'),
  ('bx/200bx_base_A', 'Taiga Shimizu', 'Schneemann', 'Snowman', 'Hat in Sapporo nur auf Eis gelernt. Trockener Asphalt verwirrt ihn bis heute.', 'Only ever learned to drive on ice in Sapporo. Dry asphalt still confuses him.', 'white'),
  ('bx/200bx_type_l_M', 'Shō Murakami', 'Ramen-Sho', 'Ramen Sho', 'Arbeitet in einer Miso-Ramen-Bude. Sein Auto riecht nach Butter und Mais.', 'Works at a miso ramen stand. His car smells of butter and corn.'),
  ('bx/200bx_type_l_A', 'Yūki Fujii', 'Der Schlichter', 'The Mediator', 'Schlichtet jeden Klappscheinwerfer-Streit und fängt dann einen neuen an.', 'Settles every pop-up headlight argument and then starts a new one.', 'navy'),
  ('bx/200bx_type_ls_M', 'Ryōta Hokuto', 'Kleiner Bär', 'Little Bear', 'Daisukes Cousin. Hat einen Bären-Aufkleber, den er für Aerodynamik hält.', 'Daisuke\'s cousin. Has a bear sticker he believes is aerodynamic.'),
  ('bx/200bx_type_ls_A', 'Hikaru Abe', 'Fernlicht', 'High Beam', 'Fährt immer mit Fernlicht. Nicht aus Bosheit, er weiß einfach nicht, wo der Schalter ist.', 'Always drives on high beam. Not out of spite, he just cannot find the switch.', 'red'),
 ]),
dict(id='t_kombi', name='Kombi Papas', jp='コンビパパ', color='#a1887f', tier=3, region='shizuoka',
 desc=('Väter mit Kombis, Kindersitzen und erstaunlich viel Ehrgeiz. Wenn die Familie schläft, wird der Ring zur Rennstrecke.',
       'Dads with estate cars, child seats and an alarming amount of ambition. When the family sleeps, the loop becomes a race track.'),
 leader=('van/street_tuned', 'Kōji Ōkubo', 'Super-Papa', 'Super Dad',
   'Hat fünf Kinder und einen getunten Van, weil kein Kombi genug Platz hatte. Fährt mit Babyschale als Ballast.',
   'Has five kids and a tuned van because no estate was big enough. Races with a baby seat as ballast.'),
 members=[
  ('sunburst2/base_EU_wagon_M', 'Hiroki Saitō', 'Elternabend', 'Parents\' Evening', 'Kommt direkt vom Elternabend. Hat dort eine Rede über Verkehrssicherheit gehalten.', 'Comes straight from parents\' evening. Gave a speech about road safety there.', 'beige'),
  ('sunburst2/base_EU_wagon_CVT', 'Kenta Ōkubo', 'Kinderwagen', 'Pushchair', 'Kōjis Bruder. Hat den Kinderwagen immer im Kofferraum, auch ohne Kind.', 'Kōji\'s brother. Always keeps the pushchair in the boot, even without a child.'),
  ('sunburst2/base_wagon_CVT', 'Makoto Yasuda', 'Windelwechsler', 'Nappy Changer', 'Wechselt Windeln in 14 Sekunden. Reifen in 12.', 'Changes nappies in 14 seconds. Tyres in 12.', 'silver'),
  ('sunburst2/comfort_wagon_M', 'Takashi Mori', 'Grillmeister', 'Grill Master', 'Hat einen Grill auf dem Dachträger. Grillt nach jedem Sieg. Grillt auch nach jeder Niederlage.', 'Has a barbecue on the roof rack. Grills after every win. Grills after every loss too.'),
  ('sunburst2/comfort_wagon_CVT', 'Norihiko Endō', 'Ikea-Papa', 'Flatpack Dad', 'Hat ein komplettes Regal im Kofferraum. Seit drei Jahren. Noch nicht aufgebaut.', 'Has an entire flat-pack shelf in his boot. For three years. Still not assembled.'),
  ('sunburst2/sport_EU_wagon_M', 'Daichi Hara', 'Fußball-Papa', 'Soccer Dad', 'Fährt samstags zum Fußball und nachts zum Ring. Brüllt in beiden Fällen ins Leere.', 'Drives to football on Saturdays and the loop at night. Shouts at nobody in both cases.', 'green'),
  ('sunburst2/sport_EU_wagon_DCT', 'Yusaku Tomita', 'Hausmann', 'House Husband', 'Hat das Abendessen vorgekocht und genau 40 Minuten bis zur Rückkehr seiner Frau.', 'Pre-cooked dinner and has exactly 40 minutes before his wife gets home.'),
  ('sunburst2/sport_S_wagon_M', 'Kazuya Ōmura', 'Allrad-Opa', 'AWD Grandpa', 'Ist eigentlich schon Opa, nennt sich aber weiter Papa. Seine Enkel finden das peinlich.', 'Is a grandpa really, but still calls himself a dad. His grandkids find it embarrassing.'),
  ('sunburst2/sport_S_wagon_DCT', 'Shinobu Kato', 'Schulweg', 'School Run', 'Kennt jede Abkürzung zur Schule. Und jede auf dem Ring. Es sind dieselben.', 'Knows every shortcut to school. And every shortcut on the loop. They are the same ones.', 'navy'),
  ('sunburst2/sport_RS_wagon_M', 'Hayato Ichikawa', 'Dachbox', 'Roof Box', 'Fährt mit Dachbox. Was darin ist, weiß niemand. Er fährt aber vorsichtiger, seit sie mal getickt hat.', 'Races with a roof box. Nobody knows what is in it. He has been more careful since it started ticking.'),
  ('sunburst2/sport_RS_wagon_DCT', 'Takumi Ōkubo', 'Ältester Sohn', 'Eldest Son', 'Kōjis Sohn. Darf erst seit gestern Auto fahren und schon heute Rennen.', 'Kōji\'s son. Only got his licence yesterday and is already racing today.'),
  ('sunburst2/sport_RS2_wagon_DCT', 'Mamoru Fuse', 'Spoiler-Papa', 'Spoiler Dad', 'Hat einen Heckflügel auf seinen Kombi geschraubt. Seine Frau nennt ihn seitdem nur noch Flügel.', 'Bolted a wing onto his estate. His wife has called him Wing ever since.'),
 ]),
dict(id='t_pocket', name='Pocket Rockets', jp='ポケットロケッツ', color='#ffd54f', tier=4, region='kochi',
 desc=('Kleine Autos, große Klappe. Die Pocket Rockets aus Kōchi wiegen weniger als dein Kofferraum und bremsen später, als du denkst.',
       'Small cars, big mouths. The Pocket Rockets from Kōchi weigh less than your boot and brake later than you think.'),
 leader=('etkc/kc4_street_tuned_M', 'Mikio Saitō', 'Der Raketenmann', 'Rocket Man',
   'Sagt, ein echtes Pocket Rocket muss aus Deutschland kommen. Hat sich deshalb einen Kc4 importieren lassen und redet seitdem mit Akzent.',
   'Says a true pocket rocket must come from Germany. Imported a Kc4 and has spoken with an accent ever since.'),
 members=[
  ('covet/type_LS_M', 'Kotarō Mizuno', 'Feuerwerk', 'Firework', 'Seine Fehlzündungen klingen wie ein Sommerfest. Die Kinder in der Straße lieben ihn.', 'His backfires sound like a summer festival. The kids on his street love him.'),
  ('covet/type_LS_A', 'Ayame Kitano', 'Taschenformat', 'Pocket Size', 'Ist 1,52 m groß und fährt deshalb mit einem Kissen. Das Kissen hat einen eigenen Namen.', 'Is 1.52 m tall and drives with a cushion. The cushion has its own name.', 'lime'),
  ('covet/15gtz_turbo_M', 'Ryūsei Arima', 'Sternschnuppe', 'Shooting Star', 'Ist schnell weg und kommt nie wieder. Leider auch seine Turbolader.', 'Gone in a flash and never seen again. Unfortunately so are his turbochargers.'),
  ('covet/15gtz_turbo2_M', 'Kaede Nomoto', 'Turbo II', 'Turbo II', 'Hat ein Turbo-II-Tattoo. Am Knöchel, wo sonst.', 'Has a Turbo II tattoo. On the ankle, where else.', 'orange'),
  ('covet/gtz', 'Tsubasa Ide', 'Flügelchen', 'Little Wing', 'Heißt übersetzt Flügel und hat keinen. Das stört ihn mehr, als er zugibt.', 'His name means wings and his car has none. It bothers him more than he admits.'),
  ('covet/runner', 'Gen Yanagi', 'Gummiband', 'Rubber Band', 'Fällt zurück und schnellt wieder vor. Wie ein Gummiband. Reißt auch manchmal.', 'Falls back and snaps forward again. Like a rubber band. Sometimes snaps.'),
  ('covet/custom', 'Mirai Toda', 'Zukunft', 'Future', 'Ihr Name bedeutet Zukunft. Ihr Auto ist von 1986. Sie findet das poetisch.', 'Her name means future. Her car is from 1986. She finds that poetic.'),
 ]),
dict(id='t_hoshikuzu', name='Hoshikuzu Rally-dan', jp='星屑ラリー団', color='#81d4fa', tier=5, region='sapporo',
 desc=('Rallye-Fans, die Schotter vermissen und deshalb nachts den Ring mit Allrad bügeln. Sie springen über jede Fuge, als wäre sie eine Kuppe.',
       'Rally fans who miss gravel and iron out the loop at night with all-wheel drive. They jump every expansion joint like it was a crest.'),
 leader=('vivace/ardente_rally_asphalt', 'Takeo Kitahara', 'Kometenschweif', 'Comet Tail',
   'Ist dreimal bei einer Rallye in Europa gestartet und hat seinen Beifahrer dort vergessen. Der kommt angeblich bald nach.',
   'Started three rallies in Europe and forgot his co-driver there. He is supposedly coming home soon.'),
 members=[
  ('sunburst2/sport_EU_M', 'Shōta Kiyohara', 'Beifahrer', 'Co-Driver', 'Liest beim Fahren seinen eigenen Aufschrieb vor. Links drei, Kuppe, nicht lupfen. Auf der Stadtautobahn.', 'Reads his own pace notes out loud. Left three, crest, don\'t lift. On an urban expressway.', 'blue'),
  ('sunburst2/sport_EU_DCT', 'Erina Kaji', 'Schotterprinzessin', 'Gravel Princess', 'Hat noch Schotter von 2019 im Radkasten und weigert sich, ihn rauszumachen.', 'Still has gravel from 2019 in her wheel arches and refuses to remove it.'),
  ('sunburst2/sport_S_M', 'Hideki Mitsui', 'Sprungschanze', 'Ski Jump', 'Nimmt jede Bodenwelle mit Anlauf. Sein Auto war schon öfter in der Luft als ein Pilot.', 'Takes every bump at full run-up. His car has spent more time airborne than a pilot.'),
  ('sunburst2/sport_S_DCT', 'Nanami Kiyohara', 'Gaspedal', 'Throttle', 'Shōtas Schwester. Hört nicht auf seinen Aufschrieb und ist trotzdem schneller.', 'Shōta\'s sister. Ignores his pace notes and is faster anyway.', 'yellow'),
  ('sunburst2/sport_RS_M', 'Kōsuke Hirai', 'Schlammbad', 'Mud Bath', 'Wäscht sein Auto aus Prinzip nie. Der Dreck sei Teil der Aerodynamik.', 'Never washes his car on principle. The dirt is part of the aerodynamics.'),
  ('sunburst2/sport_RS_DCT', 'Ai Sekiguchi', 'Sterngucker', 'Stargazer', 'Fährt nur bei klarem Himmel, damit sie zwischendurch nach Sternbildern sehen kann.', 'Only races under a clear sky so she can look for constellations along the way.', 'midnight'),
  ('sunburst2/sport_RS2_DCT', 'Hayao Kitahara', 'Kleiner Komet', 'Little Comet', 'Takeos Sohn. Hat den Flügel selbst gebaut, aus einem Bügelbrett.', 'Takeo\'s son. Built the wing himself, out of an ironing board.'),
 ]),
dict(id='t_sbr', name='Hirochi Blood', jp='ヒロチの血', color='#ef5350', tier=7, region='toyota',
 desc=('Werksangestellte, die ihr eigenes Produkt lieben. Nur SBR, nur Hirochi, keine Diskussion. Manche fahren jetzt elektrisch, die anderen reden nicht mehr mit ihnen.',
       'Factory workers who love their own product. Only SBR, only Hirochi, no discussion. Some drive electric now, and the others no longer speak to them.'),
 leader=('sbr/electric_800', 'Seiji Hirochika', 'Hochspannung', 'High Voltage',
   'Hat den eSBR 800 mitentwickelt und sagt, Verbrenner seien ein Hobby für Nostalgiker. Lädt sein Auto heimlich an der Werkssteckdose.',
   'Co-developed the eSBR 800 and calls combustion engines a hobby for nostalgics. Secretly charges his car at the factory socket.', 'electric'),
 members=[
  ('sbr/base_RWD_M', 'Kōhei Nakamoto', 'Fließband', 'Assembly Line', 'Schraubt tagsüber SBR zusammen und weiß genau, welche Schraube bei deinem fehlt.', 'Assembles SBRs by day and knows exactly which bolt is missing on yours.', 'white'),
  ('sbr/base_RWD_DCT', 'Mariko Tsuji', 'Qualitätskontrolle', 'Quality Control', 'Prüft jedes Auto auf Spaltmaße. Deins hat sie schon von weitem durchfallen lassen.', 'Checks every car for panel gaps. Failed yours from a distance.'),
  ('sbr/S_RWD_M', 'Hiroshi Kanda', 'Werksmeister', 'Foreman', 'Arbeitet seit 30 Jahren bei Hirochi und hat ein Firmenlogo als Tattoo. Auf der Stirn.', 'Has worked at Hirochi for 30 years and has the company logo tattooed. On his forehead.', 'red'),
  ('sbr/S_RWD_DCT', 'Kenzō Ōtsuka', 'Testfahrer', 'Test Driver', 'Fährt seit Jahren Prototypen. Glaubt, dass auch dein Auto ein Erlkönig ist.', 'Has driven prototypes for years. Thinks your car is a disguised prototype too.'),
  ('sbr/S_AWD_M', 'Yumi Hirochika', 'Erbin', 'Heiress', 'Seijis Schwester. Fährt aus Protest gegen ihren Bruder einen Benziner. Laut.', 'Seiji\'s sister. Drives petrol in protest against her brother. Loudly.', 'pearl'),
  ('sbr/S_AWD_DCT', 'Tomoya Kuwabara', 'Gewerkschaft', 'Union Rep', 'Fordert vor jedem Rennen eine Pause. Und Zuschläge für Nachtarbeit.', 'Demands a break before every race. And a night-shift bonus.'),
  ('sbr/electric_300', 'Shizuka Mori', 'Flüsterin', 'Whisperer', 'Ihr eSBR ist so leise, dass du sie erst merkst, wenn sie schon vor dir ist.', 'Her eSBR is so quiet you only notice her when she is already ahead.', 'electric'),
  ('sbr/electric_500', 'Denki Yamato', 'Kurzschluss', 'Short Circuit', 'Heißt wirklich Denki, und fährt wirklich elektrisch. Seine Eltern hatten einen Plan.', 'Really is named Denki and really drives electric. His parents had a plan.'),
 ]),
]
